#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    long long k;
    cin >> s >> k;
    // Survivors are always an arithmetic progression head, head+step, ...
    long long count = (long long)s.size() * k, head = 0, step = 1;
    bool left = true;
    while (count > 1) {
        if (left || count % 2) head += step;
        count /= 2;
        step *= 2;
        left = !left;
    }
    cout << s[head % s.size()] << "\n";
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        long k = sc.nextLong();
        // Survivors are always an arithmetic progression head, head+step, ...
        long count = s.length() * k, head = 0, step = 1;
        boolean left = true;
        while (count > 1) {
            if (left || count % 2 == 1) head += step;
            count /= 2;
            step *= 2;
            left = !left;
        }
        System.out.println(s.charAt((int) (head % s.length())));
    }
}

package main

import "fmt"

func main() {
	var s string
	var k int
	fmt.Scan(&s, &k)
	// Survivors are always an arithmetic progression head, head+step, ...
	count, head, step := len(s)*k, 0, 1
	left := true
	for count > 1 {
		if left || count%2 == 1 {
			head += step
		}
		count /= 2
		step *= 2
		left = !left
	}
	fmt.Println(string(s[head%len(s)]))
}
